H('102.d.2.C',3,"Industrial processes in cabinet manufacturing include:","CNC cutting and edge banding",["Hand carving only","Painting only","Weaving"],"Automation increases accuracy.")
H('102.d.2.C',4,"A CNC router in a cabinet shop is used to:","Cut parts precisely from digital plans",["Sweep floors","Print invoices","Paint cabinets"],"CNC follows programmed paths.")
